    border: solid rgba(0, 0, 0, 0.15) 1px;
    -webkit-box-shadow: 0 6px 12px rgba(0, 0, 0, 0.175);
    box-shadow: 0 6px 12px rgba(0, 0, 0, 0.175);
  }
}
thead.r-fixedhead {
  background-color: #FFFFFF;
}
.table {
  background: #fff;
}
.rnr-details-popup {
  background-color: #FFFFFF;
  border: 1px solid #E5E5EA;
  -webkit-box-shadow: 0 1px 1px rgba(0, 0, 0, 0.05);
  box-shadow: 0 1px 1px rgba(0, 0, 0, 0.05);
}
.rnr-details-popup {
  background-color: #FFFFFF;
  border: 1px solid #E5E5EA;
  -webkit-box-shadow: 0 1px 1px rgba(0, 0, 0, 0.05);
  box-shadow: 0 1px 1px rgba(0, 0, 0, 0.05);
}
.panel-heading:after {
  clear: both;
  content: ' ';
  display: block;
}
.rnr-hiddenelem {
  display: none;
}
/*Begin Misc loading styles*/
.rnr-loading.show {
  display: block;
}
.rnr-loading.hide {
  display: none;
}
.rnr-loading .fon {
  position: absolute;
  width: 100%;
  height: 100%;
  z-index: 3000;
  background-color: #000;
  opacity: 0.2;
  filter: alpha(opacity=20);
}
.rnr-loading .main {
  position: absolute;
  z-index: 4000;
  padding: 1em 2em;
}
/*for printpage*/
.rnr-loading-print .main {
  display: inline-block;
  padding: 1em 2em;
  margin-bottom: 10px;
  position: absolute;
  z-index: 1000;
}
/*End for printpage*/
.rnr-loading .text,
.rnr-loading-print .text {
  margin-left: 8pt;
  font-size: 9pt;
  vertical-align: middle;
  color: #336699;
  font-weight: bold;
}
/*End Misc loading styles*/

/* ============================================================
   GLASSMORPHISM – Frosted glass MacBook style
   ============================================================ */

/* Base glass utility */
.glass,
.panel,
.r-grid > .panel,
.modal-content,
.dropdown-menu,
.popover,
.navbar,
.navbar-default,
.navbar-inverse,
.well,
.thumbnail,
.list-group,
.r-box-left,
.r-box-right,
.filterPanelContainer .panel,
[data-dashboard] [data-dashtype] > .panel,
.rnr-details-popup,
.r-cookie-banner,
.bs-popup,
.panel.form-section {
  background: rgba(255, 255, 255, 0.55) !important;
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  backdrop-filter: saturate(180%) blur(20px);
  border: 1px solid rgba(255, 255, 255, 0.45) !important;
  box-shadow:
    0 4px 24px rgba(0, 0, 0, 0.06),
    0 1px 2px rgba(0, 0, 0, 0.04),
    inset 0 1px 0 rgba(255, 255, 255, 0.6) !important;
}

/* Stronger glass for elevated surfaces */
.modal-content,
.dropdown-menu,
.popover,
.rnr-details-popup {
  background: rgba(255, 255, 255, 0.72) !important;
  -webkit-backdrop-filter: saturate(200%) blur(28px);
  backdrop-filter: saturate(200%) blur(28px);
  border: 1px solid rgba(255, 255, 255, 0.55) !important;
  border-radius: 14px !important;
  box-shadow:
    0 12px 40px rgba(0, 0, 0, 0.12),
    0 4px 12px rgba(0, 0, 0, 0.06),
    inset 0 1px 0 rgba(255, 255, 255, 0.7) !important;
}

/* Panel headings / footers – lighter glass */
.panel > .panel-heading,
.panel > .panel-footer,
.r-grid > .panel > .panel-heading,
.r-grid > .panel > .panel-footer {
  background: rgba(255, 255, 255, 0.35) !important;
  -webkit-backdrop-filter: blur(12px);
  backdrop-filter: blur(12px);
  border-color: rgba(255, 255, 255, 0.3) !important;
  border-bottom: 1px solid rgba(0, 0, 0, 0.04) !important;
}

.panel > .panel-footer {
  border-top: 1px solid rgba(0, 0, 0, 0.04) !important;
  border-bottom: none !important;
}

/* Navbar glass */
.navbar,
.navbar-default,
.navbar-inverse,
[data-location="supertop"] {
  background: rgba(255, 255, 255, 0.65) !important;
  -webkit-backdrop-filter: saturate(180%) blur(24px);
  backdrop-filter: saturate(180%) blur(24px);
  border: none !important;
  border-bottom: 1px solid rgba(0, 0, 0, 0.06) !important;
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.8) inset,
              0 4px 20px rgba(0, 0, 0, 0.04) !important;
}

/* Left sidebar / vertical bar */
.r-left,
.r-vbar-page .r-left {
  background: rgba(255, 255, 255, 0.5) !important;
  -webkit-backdrop-filter: saturate(180%) blur(24px);
  backdrop-filter: saturate(180%) blur(24px);
  border-right: 1px solid rgba(0, 0, 0, 0.05) !important;
}

/* Cards / dashboard boxes */
.r-box-left,
.r-box-right,
[data-dashboard] [data-dashtype] > .panel {
  border-radius: 16px !important;
  overflow: hidden;
}

/* Buttons – subtle glass on default */
.btn-default {
  background: rgba(255, 255, 255, 0.55) !important;
  -webkit-backdrop-filter: blur(10px);
  backdrop-filter: blur(10px);
  border: 1px solid rgba(0, 0, 0, 0.08) !important;
  color: #1D1D1F !important;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.04),
              inset 0 1px 0 rgba(255, 255, 255, 0.7) !important;
}
.btn-default:hover,
.btn-default:focus {
  background: rgba(255, 255, 255, 0.8) !important;
  border-color: rgba(0, 0, 0, 0.12) !important;
  color: #1D1D1F !important;
}

/* Primary still solid but with soft glass edge */
.btn-primary {
  background: linear-gradient(180deg, #0A84FF 0%, #007AFF 100%) !important;
  border: 1px solid rgba(255, 255, 255, 0.25) !important;
  box-shadow: 0 2px 8px rgba(0, 122, 255, 0.3),
              inset 0 1px 0 rgba(255, 255, 255, 0.25) !important;
}

/* Form controls – light glass */
.form-control {
  background: rgba(255, 255, 255, 0.6) !important;
  -webkit-backdrop-filter: blur(8px);
  backdrop-filter: blur(8px);
  border: 1px solid rgba(0, 0, 0, 0.08) !important;
  box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.03) !important;
}
.form-control:focus {
  background: rgba(255, 255, 255, 0.85) !important;
  border-color: rgba(0, 122, 255, 0.5) !important;
  box-shadow: 0 0 0 3px rgba(0, 122, 255, 0.15),
              inset 0 1px 2px rgba(0, 0, 0, 0.03) !important;
}

/* Tables – keep readable */
.table,
.table > thead > tr > th {
  background: transparent !important;
}
.table-striped > tbody > tr:nth-of-type(odd) {
  background-color: rgba(0, 0, 0, 0.02) !important;
}
.table-hover > tbody > tr:hover {
  background-color: rgba(0, 122, 255, 0.06) !important;
}

/* Body & page background – soft gradient for glass to show against */
body,
body.function-dashboard,
body[data-panel-bg] {
  background: linear-gradient(160deg, #F5F5F7 0%, #E8E8ED 45%, #F2F2F7 100%) fixed !important;
  background-color: #F5F5F7 !important;
}

/* Modal backdrop – darker so glass stands out */
.modal-backdrop {
  background-color: rgba(0, 0, 0, 0.25) !important;
  -webkit-backdrop-filter: blur(4px);
  backdrop-filter: blur(4px);
}
.modal-backdrop.in {
  opacity: 1 !important;
}

/* Dropdown items */
.dropdown-menu > li > a:hover,
.dropdown-menu > li > a:focus,
.dropdown-menu > .active > a {
  background: rgba(0, 122, 255, 0.12) !important;
  color: #007AFF !important;
}

/* Search suggest / popups */
.search_suggest,
.rnr-details-popup {
  background: rgba(255, 255, 255, 0.78) !important;
  -webkit-backdrop-filter: blur(24px);
  backdrop-filter: blur(24px);
  border: 1px solid rgba(255, 255, 255, 0.5) !important;
  border-radius: 12px !important;
}

/* Filter panel */
.filterPanelContainer .panel {
  border-radius: 12px !important;
}

/* Cookie banner */
.r-cookie-banner {
  background: rgba(30, 30, 32, 0.7) !important;
  -webkit-backdrop-filter: blur(20px);
  backdrop-filter: blur(20px);
  border-top: 1px solid rgba(255, 255, 255, 0.1) !important;
  color: #F5F5F7 !important;
}

/* Fallback when backdrop-filter not supported */
@supports not ((-webkit-backdrop-filter: blur(1px)) or (backdrop-filter: blur(1px))) {
  .panel,
  .r-grid > .panel,
  .modal-content,
  .dropdown-menu,
  .navbar,
  .r-left,
  .btn-default,
  .form-control {
    background: rgba(255, 255, 255, 0.92) !important;
  }
}

/* Smooth transitions for glass elements */
.panel,
.modal-content,
.dropdown-menu,
.btn,
.form-control,
.navbar {
  transition: background 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;
}

